<title>SIEGE LINE — Meridian Yards | a three.js tactical FPS</title>
<style>
  /* Look plan: dusk steel blues and concrete, warm sodium lamps, one hazard amber.
     The same names live in src/palette.js, so the HUD and the 3D scene share a palette. */
  :root {
    --canvas: #171a20;
    --surface: #22262e;
    --hairline: #31363f;
    --ink: #e8e4d8;
    --muted: #9aa3ad;
    --accent: #f2a71b;
    --vanguard: #4da3ff;
    --jackal: #ff5a3c;
    --site-a: #37c978;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
    user-select: none;
