  /* Crosshair: four bars whose gap grows with spread, so stopping to aim pays. */
  #crosshair {
    --gap: 6px;
    position: fixed; left: 50%; top: 50%; width: 30px; height: 30px;
    transform: translate(-50%, -50%);
  }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; box-shadow: 0 0 2px #000; }
  #crosshair i:nth-child(1) { left: 14px; top: calc(15px - var(--gap) - 7px); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 14px; top: calc(15px + var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 14px; left: calc(15px - var(--gap) - 7px); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 14px; left: calc(15px + var(--gap)); height: 2px; width: 7px; }
  #crosshair::after {
    content: ''; position: absolute; left: 14px; top: 14px; width: 2px; height: 2px;
    background: var(--accent); border-radius: 50%;
  }

  #hitmarker {
    position: fixed; left: 50%; top: 50%; width: 26px; height: 26px;
